WITH promo_returns AS (SELECT p.p_promo_id, p.p_promo_name, CASE WHEN p.p_cost > 0 THEN 'Paid' ELSE 'Free' END AS promo_type, COUNT(DISTINCT wr.wr_order_number) AS num_returns, SUM(wr.wr_net_loss) AS total_net_loss, AVG(wr.wr_return_quantity) AS avg_qty_per_return FROM promotion p JOIN date_dim d_start ON p.p_start_date_sk = d_start.d_date_sk JOIN date_dim d_end ON p.p_end_date_sk = d_end.d_date_sk JOIN web_returns wr ON wr.wr_returned_date_sk BETWEEN p.p_start_date_sk AND p.p_end_date_sk JOIN web_page wp ON wr.wr_web_page_sk = wp.wp_web_page_sk WHERE p.p_discount_active = 'Y' AND wp.wp_type = 'Landing' GROUP BY p.p_promo_id, p.p_promo_name, CASE WHEN p.p_cost > 0 THEN 'Paid' ELSE 'Free' END HAVING SUM(wr.wr_net_loss) > 0) SELECT p_promo_id, p_promo_name, promo_type, num_returns, total_net_loss, avg_qty_per_return, RANK() OVER (ORDER BY total_net_loss DESC) AS loss_rank FROM promo_returns ORDER BY loss_rank
